import{_ as e,o as a,c as i,an as l}from"./chunks/framework.CZSJrt3Z.js";const n="/EegFun.jl/v0.8/assets/simulate_erp.nOIBNgYw.png",m=JSON.parse('{"title":"Simulate ERP — Signal Averaging Demo","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/teaching/erp/simulate_erp.md","filePath":"tutorials/teaching/erp/simulate_erp.md","lastUpdated":null}'),s={name:"tutorials/teaching/erp/simulate_erp.md"};function r(o,t,h,g,d,p){return a(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="Simulate-ERP-—-Signal-Averaging-Demo" tabindex="-1">Simulate ERP — Signal Averaging Demo <a class="header-anchor" href="#Simulate-ERP-—-Signal-Averaging-Demo" aria-label="Permalink to &quot;Simulate ERP — Signal Averaging Demo {#Simulate-ERP-—-Signal-Averaging-Demo}&quot;">​</a></h1><p>Interactive ERP simulator for teaching how trial averaging extracts signals from noise.</p><p><img src="'+n+`" alt=""></p><h2 id="What-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#What-it-shows" aria-label="Permalink to &quot;What it shows {#What-it-shows}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Element</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;">Grey lines</td><td style="text-align:right;">Individual simulated EEG trials with realistic 1/f background noise</td></tr><tr><td style="text-align:right;">Blue line</td><td style="text-align:right;">Trial-average ERP — clarifies as more trials are added</td></tr><tr><td style="text-align:right;">Components</td><td style="text-align:right;">Up to 5 independent ERP components, each shaped as a single cosine lobe (the central peak of a cosine wave, masked to ±π/2) to produce a smooth, bell-like waveform</td></tr></tbody></table><p><strong>The core insight:</strong> The signal-to-noise ratio of the ERP average scales with √N (where N is the number of trials). Doubling the number of trials improves SNR by ~41%; to <em>halve</em> the noise, you need 4× as many trials.</p><p>The background noise uses a realistic human EEG power spectrum (1/f structure), not white noise — so individual trials look like real EEG epochs rather than random static.</p><p>This demo builds directly on <a href="./../signal_processing/signal_example_composition">Signal Example 2</a>: the ERP waveform you see in the average is a real-world instance of multiple frequency components summing together, now embedded in realistic noise.</p><h2 id="Things-to-Try" tabindex="-1">Things to Try <a class="header-anchor" href="#Things-to-Try" aria-label="Permalink to &quot;Things to Try {#Things-to-Try}&quot;">​</a></h2><ul><li><p>Start with 1 trial and a single active component — the ERP equals the single trial.</p></li><li><p>Add noise and increase trials to watch the ERP &quot;emerge&quot; from the background activity.</p></li><li><p>Activate a second component at a different latency to show how components superpose — and try setting one to a <strong>negative amplitude</strong> to model typical ERP polarities (N1 negative, P3 positive).</p></li><li><p>Introduce <strong>latency jitter</strong> to show how trial-to-trial variability smears and attenuates the average — a key confound in real ERP research.</p></li><li><p>Introduce <strong>amplitude jitter</strong> to show how variability in peak amplitude scales the average downward.</p></li></ul><h2 id="Controls" tabindex="-1">Controls <a class="header-anchor" href="#Controls" aria-label="Permalink to &quot;Controls {#Controls}&quot;">​</a></h2><p>Each component has its own row of controls in the right panel.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Control</th><th style="text-align:right;">Range</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;">Number of Trials</td><td style="text-align:right;">1–500</td><td style="text-align:right;">Trials to average</td></tr><tr><td style="text-align:right;">Noise Amplitude</td><td style="text-align:right;">0–20</td><td style="text-align:right;">Background 1/f EEG noise level</td></tr><tr><td style="text-align:right;">Active toggle (×5)</td><td style="text-align:right;">on/off</td><td style="text-align:right;">Enable or disable each component</td></tr><tr><td style="text-align:right;">Freq (×5)</td><td style="text-align:right;">0.1–5.0 Hz</td><td style="text-align:right;">Component shape (cosine frequency)</td></tr><tr><td style="text-align:right;">Amp (×5)</td><td style="text-align:right;">−10 to 10 μV</td><td style="text-align:right;">Peak amplitude (negative = typical N-wave polarity)</td></tr><tr><td style="text-align:right;">Latency (×5)</td><td style="text-align:right;">0–1000 ms (steps: 10 ms)</td><td style="text-align:right;">Peak latency</td></tr><tr><td style="text-align:right;">Amp Jitter (×5)</td><td style="text-align:right;">0–20 (Gaussian SD)</td><td style="text-align:right;">Trial-to-trial amplitude variability</td></tr><tr><td style="text-align:right;">Lat Jitter (×5)</td><td style="text-align:right;">0–50 ms (Gaussian SD)</td><td style="text-align:right;">Trial-to-trial latency variability</td></tr></tbody></table><h2 id="See-Also" tabindex="-1">See Also <a class="header-anchor" href="#See-Also" aria-label="Permalink to &quot;See Also {#See-Also}&quot;">​</a></h2><ul><li><p>Luck, S. J. (2014). <em>An Introduction to the Event-Related Potential Technique</em> (2nd ed.). MIT Press. — Chapter 8 (averaging and signal-to-noise ratio)</p></li><li><p><a href="./../signal_processing/signal_example_sampling">Signal Example — Sampling</a> — Nyquist theorem and signal reconstruction</p></li><li><p><a href="./../signal_processing/signal_example_composition">Signal Example — Composition</a> — signal composition and filtering</p></li><li><p><a href="./../machine_learning/signal_example_decoding">Simulate Decoding</a> — multivariate pattern classification on synthetic EEG</p></li></ul><h2 id="Code" tabindex="-1">Code <a class="header-anchor" href="#Code" aria-label="Permalink to &quot;Code {#Code}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EegFun</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EegFun</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">simulate_erp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div>`,17)])])}const u=e(s,[["render",r]]);export{m as __pageData,u as default};
